"""Optional Rebirth hash cache, generated by a cancellable bridge subprocess."""

import json
import os
from pathlib import Path
import subprocess
import tempfile

import bpy

from ...core.bridge import gargoyle_command
from ...games.rebirth.profile import PROFILE


_job = None
STATUS = ""


def cache_path():
    # User data survives add-on updates and keeps generated data out of packages.
    root = bpy.utils.user_resource("DATAFILES")
    if not root:
        raise RuntimeError("Blender's user data directory is unavailable.")
    return Path(root) / "talisman" / "rebirth" / "texture_hashes.csv"


def running():
    return _job is not None


def _redraw():
    for window in bpy.context.window_manager.windows:
        for area in window.screen.areas:
            area.tag_redraw()


def _close(job):
    if job["process"].poll() is None:
        job["process"].kill()
    job["process"].wait()
    job["output"].close()
    job["directory"].cleanup()


def cancel():
    global _job, STATUS
    if _job is not None:
        job, _job = _job, None
        _close(job)
        STATUS = "Generation cancelled. Any previous lookup is unchanged."
    if bpy.app.timers.is_registered(_poll):
        bpy.app.timers.unregister(_poll)
    _redraw()


def _poll():
    global _job, STATUS
    job = _job
    if job is None:
        return None
    if job["process"].poll() is None:
        # Read a separate handle so polling cannot move the child's write offset.
        with open(job["log"], encoding="utf-8", errors="replace") as stream:
            stream.seek(job["position"])
            lines = stream.readlines()
            job["position"] = stream.tell()
        for line in lines:
            try:
                result = json.loads(line)
                if result.get("textureHashes"):
                    STATUS = f"Scanning packages: {result['scanned']:,} / {result['total']:,} ({result['count']:,} hashes)"
            except (ValueError, AttributeError, KeyError):
                pass
        _redraw()
        return 0.25
    try:
        # Parse the final result afresh; a progress line may have been read mid-write.
        result = None
        with open(job["log"], encoding="utf-8", errors="replace") as stream:
            for line in stream:
                try:
                    value = json.loads(line)
                    if isinstance(value, dict) and value.get("textureHashes") and value.get("complete"):
                        result = value
                except ValueError:
                    pass
        if job["process"].returncode or not result or not result.get("count") or not job["csv"].is_file():
            raise RuntimeError("Generation failed. Check the Rebirth folder, mappings and Oodle DLL. Any previous lookup is unchanged.")
        os.replace(job["csv"], job["target"])
        from . import material
        material.load_hash_table()
        STATUS = f"Generated {result['count']:,} texture hashes."
        if result.get("failures"):
            STATUS += f" Skipped {result['failures']:,} unreadable packages."
    except (OSError, RuntimeError) as error:
        STATUS = str(error)
    finally:
        _job = None
        _close(job)
    _redraw()
    return None


def start(preferences):
    global _job, STATUS
    if running():
        raise RuntimeError("Texture hash generation is already running.")
    paths = PROFILE.paths_from_preferences(preferences, bpy.path.abspath)
    if not paths.install_root or not Path(paths.install_root).is_dir():
        raise ValueError("Choose a valid Rebirth Install Folder first.")
    if not paths.usmap_path or not Path(paths.usmap_path).is_file():
        raise ValueError("Choose the Rebirth Mapping File first.")
    if not paths.oodle_dll or not Path(paths.oodle_dll).is_file():
        raise ValueError("Choose the shared Oodle DLL first.")
    target = cache_path()
    target.parent.mkdir(parents=True, exist_ok=True)
    directory = tempfile.TemporaryDirectory(prefix="generating-", dir=target.parent)
    csv_path = Path(directory.name) / "texture_hashes.csv"
    log_path = Path(directory.name) / "progress.jsonl"
    output = None
    try:
        output = open(log_path, "wb")
        command = gargoyle_command(Path(__file__).resolve().parents[2], PROFILE, paths,
                                   str(csv_path), operation="rebirth-texture-hashes")
        process = subprocess.Popen(command, stdin=subprocess.DEVNULL, stdout=output,
                                   stderr=subprocess.DEVNULL,
                                   creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0))
    except Exception:
        if output is not None:
            output.close()
        directory.cleanup()
        raise
    _job = dict(process=process, output=output, directory=directory, csv=csv_path,
                log=log_path, target=target, position=0)
    STATUS = "Mounting Rebirth game files..."
    if bpy.app.background:
        process.wait()
        _poll()
    else:
        bpy.app.timers.register(_poll, first_interval=0.25)
    _redraw()


def unregister():
    global STATUS
    cancel()
    STATUS = ""
